def file_may_match(f_min, f_max, intervals) -> bool:
    # File stores [f_min, f_max] of curve values.
    # Query rectangle was decomposed into disjoint [lo, hi] intervals.
    # Trade-off: more intervals = tighter pruning but slower planning.
    for lo, hi in intervals:
        if f_max >= lo and f_min <= hi:
            return True
    return False

def decompose_z(q_lo_s, q_hi_s, max_intervals=8):
    # Placeholder for real recursive split: start with one loose
    # interval, then carve out the big dead gaps caused by Z jumps.
    # Cap intervals: beyond ~8-16 the planner cost exceeds scan savings.
    mid = (q_lo_s + q_hi_s) // 2
    if max_intervals <= 1 or q_hi_s - q_lo_s < 1024:
        return [(q_lo_s, q_hi_s)]
    return [(q_lo_s, mid), (mid + 1, q_hi_s)]
